-- NO ejecutar por separado: integrar en la transacción atómica del lote 02 después del despliegue y verificación HTTP 200 de todos los medios.
do $pub$
declare
  g constant uuid := 'e8238258-5fe1-4344-8851-917fa546f20b';
  es_id constant uuid := '82997c99-0b32-42e0-8e22-1617a936c949';
  j constant jsonb := $ravioli$[{"id":"82997c99-0b32-42e0-8e22-1617a936c949","recipe_group_id":"e8238258-5fe1-4344-8851-917fa546f20b","slug":"receta-raviolis-caseros","public_path":"/receta-raviolis-caseros","source_url":"https://manualdecocina.com/receta-raviolis-caseros/","language":"es","title":"Raviolis caseros de ricotta y espinaca","excerpt":"Raviolis caseros de ricotta y espinaca para 4: masa fresca de huevo, sellado paso a paso y acabado de mantequilla con salvia.","summary":"Estos raviolis caseros combinan una masa fresca de huevo con un relleno espeso de ricotta, espinaca y parmesano. Se sellan en 24 unidades y se sirven con mantequilla avellanada y salvia, sin ocultar la técnica con una salsa pesada.\n\nLa propuesta rinde 4 porciones de 6 raviolis. Calcula 70 minutos de preparación y 20 de cocción, 90 en total; el escurrido, el reposo y parte de la preparación se solapan. Cantidades, espesor de la masa, tiempos y rendimiento están pendientes de una prueba de cocina.","category":"Pastas","category_slug":"pastas","difficulty":"Media","course":"Plato principal","cuisine":"Italiana, propuesta casera","prep_time_minutes":70,"cook_time_minutes":20,"total_time_minutes":90,"servings":4,"ingredients":[{"name":"harina de trigo de uso común","amount":"320","unit":"g","group":"Masa"},{"name":"huevos grandes, sin cáscara","amount":"3","unit":"unidades (aprox. 150 g)","group":"Masa"},{"name":"agua","amount":"15","unit":"ml, solo si hace falta","group":"Masa"},{"name":"ricotta de leche entera","amount":"300","unit":"g","group":"Relleno"},{"name":"espinaca fresca","amount":"200","unit":"g","group":"Relleno"},{"name":"queso parmesano finamente rallado","amount":"40","unit":"g","group":"Relleno"},{"name":"nuez moscada molida","amount":"0.5","unit":"g","group":"Relleno"},{"name":"sal fina","amount":"5","unit":"g, dividida","group":"Relleno y cocción"},{"name":"mantequilla sin sal","amount":"40","unit":"g","group":"Acabado"},{"name":"hojas de salvia fresca","amount":"6","unit":"g","group":"Acabado"},{"name":"agua para cocer","amount":"3000","unit":"ml","group":"Cocción"}],"steps":[{"title":"Escurre la ricotta","content":"Pon los 300 g de ricotta en un colador fino sobre un cuenco, tapa y deja escurrir 30 minutos en la nevera. No la dejes a temperatura ambiente. Presiona suavemente al final, sin convertirla en una pasta seca. Esta espera está incluida en los 70 minutos de preparación y puede solaparse con la masa y la espinaca.","image_url":"/recetas/receta-raviolis-caseros/paso-01.webp","image_alt":"Raviolis caseros: escurre la ricotta"},{"title":"Cocina y seca la espinaca","content":"Lava los 200 g de espinaca y pásala a una sartén amplia aún húmeda. Cocina a fuego medio 2–3 minutos, moviendo, hasta que se marchite. Extiéndela en un plato limpio para que pierda calor; cuando se pueda manipular, exprímela con las manos limpias o un paño limpio hasta retirar la mayor cantidad de agua posible y pícala fina. La espinaca húmeda puede abrir los raviolis.","image_url":"/recetas/receta-raviolis-caseros/paso-02.webp","image_alt":"Raviolis caseros: cocina y seca la espinaca"},{"title":"Mezcla la masa","content":"Forma un hueco en 300 g de la harina y añade los 3 huevos, aproximadamente 150 g sin cáscara. Bate los huevos con tenedor y ve incorporando harina desde el borde. Amasa hasta reunir una masa firme; añade el agua de 5 en 5 ml solo si quedan partes secas después de varios minutos. Reserva los 20 g restantes de harina para la mesa y la bandeja. La absorción varía: no añadas toda el agua por obligación.","image_url":"/recetas/receta-raviolis-caseros/paso-03.webp","image_alt":"Raviolis caseros: mezcla la masa"},{"title":"Amasa y deja reposar","content":"Amasa 8–10 minutos sobre una superficie limpia hasta que la masa se vea lisa y recupere lentamente la forma al presionarla. Envuelve bien para que no se seque y deja reposar 30 minutos a temperatura ambiente fresca. Limpia la mesa y los utensilios que tocaron huevo crudo antes de preparar el relleno o manipular raviolis cocidos.","image_url":"/recetas/receta-raviolis-caseros/paso-04.webp","image_alt":"Raviolis caseros: amasa y deja reposar"},{"title":"Prepara un relleno seco","content":"Mezcla la ricotta escurrida, la espinaca picada, los 40 g de parmesano, 0,5 g de nuez moscada y 2 g de la sal. Debe quedar espeso y mantener la forma de una cucharadita. Divide visualmente en 24 porciones de unos 20 g; si se extiende o suelta líquido, refrigera 10 minutos y vuelve a comprobar. No añadas huevo al relleno de esta propuesta.","image_url":"/recetas/receta-raviolis-caseros/paso-05.webp","image_alt":"Raviolis caseros: prepara un relleno seco"},{"title":"Estira, rellena y sella","content":"Divide la masa en 4 partes y mantén 3 envueltas. Estira una parte con máquina o rodillo hasta una lámina fina de aproximadamente 1 mm; evita agujeros. Coloca 6 porciones de relleno separadas, humedece apenas el contorno con agua y cubre con otra mitad de la lámina. Expulsa el aire desde el relleno hacia fuera y presiona para sellar. Corta 6 raviolis y revisa cada borde. Repite hasta obtener 24; ponlos en bandeja con parte de la harina reservada, sin apilar. Cocina enseguida o refrigera tapados un máximo propuesto de 2 horas antes de cocer.","image_url":"/recetas/receta-raviolis-caseros/paso-06.webp","image_alt":"Raviolis caseros: estira, rellena y sella"},{"title":"Cuece los raviolis por tandas","content":"Hierve los 3 litros de agua con los 3 g de sal restantes. Mientras, derrite los 40 g de mantequilla a fuego medio-bajo con las hojas de salvia hasta que la mantequilla huela a avellana y los sólidos estén dorados, no negros; retira del fuego. Cuece los raviolis en 2 tandas para que no se peguen: remueve con suavidad y cuenta 3–5 minutos desde que el agua recupere un hervor moderado. Abre uno de prueba de la primera tanda: la pasta debe estar tierna, el sello cocido y el centro alcanzar al menos 71 °C. Si no, prolonga y vuelve a comprobar con un ravioli nuevo.","image_url":"/recetas/receta-raviolis-caseros/paso-07.webp","image_alt":"Raviolis caseros: cuece los raviolis por tandas"},{"title":"Termina, sirve y guarda","content":"Saca los raviolis con espumadera, deja escurrir unos segundos y pásalos a la sartén de mantequilla y salvia. Mueve con cuidado 30–60 segundos para cubrirlos sin romperlos. Reparte 6 raviolis por persona y sirve de inmediato. Refrigera las sobras en recipientes bajos a 4 °C o menos dentro de 2 horas, o 1 hora si el ambiente supera 32 °C; se propone consumirlas en 2 días. Recalienta solo una vez hasta 74 °C en el centro. No guardes sobrante de huevo crudo que haya tocado harina o utensilios sin higienizar.","image_url":"/recetas/receta-raviolis-caseros/paso-08.webp","image_alt":"Raviolis caseros: termina, sirve y guarda"}],"notes":"La masa y el relleno contienen trigo, huevo y lácteos. No se propone una sustitución sin gluten, sin huevo o sin lácteos dentro de esta ficha porque cambiaría hidratación, estructura y nutrición. La ricotta debe escurrirse en frío; la espinaca debe exprimirse bien. Si un ravioli tiene un borde abierto, reséllalo antes de cocer y no lo apiles. El espesor de 1 mm, el rendimiento de 24 unidades y los tiempos son objetivos editoriales pendientes de confirmación en cocina. Para congelar, coloca los raviolis crudos separados en bandeja hasta que estén firmes y pásalos a un recipiente; cocina desde congelados añadiendo tiempo y verifica al menos 71 °C en el centro. No descongeles a temperatura ambiente.","nutrition":{"calories":598.4,"protein_g":26.5,"carbs_g":65.8,"fat_g":24.9,"saturated_fat_g":14.3,"fiber_g":3.3,"sugar_g":0.9,"sodium_mg":761,"estimated":true,"serving_size":"6 raviolis de un total propuesto de 24, con una cuarta parte de la salsa","source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Ocho fichas SR Legacy verificadas; pesos comestibles propuestos sumados y divididos entre 4. Se cuentan los 320 g de harina y los 40 g de mantequilla completos, aunque en cocina pueda quedar harina de trabajo o salsa en el recipiente.","note":"Estimación informativa, no análisis del plato terminado. Marca y humedad de ricotta, tamaño real de los huevos, harina no incorporada, agua absorbida, queso y mantequilla que queden en utensilios cambian el resultado. Cantidades y rendimiento están pendientes de prueba de cocina.","inputs":[{"ingredient":"harina de trigo","edible_grams":320,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"fiber_g":2.7,"fat_g":0.98,"carbs_g":76.31,"calories":364,"protein_g":10.33,"sodium_mg":2,"saturated_fat_g":0.155,"sugar_g":0.27},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"huevo entero crudo sin cáscara","edible_grams":150,"fdc_id":171287,"fdc_description":"Egg, whole, raw, fresh","per_100g":{"calories":143,"saturated_fat_g":3.126,"protein_g":12.56,"sodium_mg":142,"sugar_g":0.37,"fat_g":9.51,"carbs_g":0.72,"fiber_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171287/nutrients"},{"ingredient":"ricotta de leche entera","edible_grams":300,"fdc_id":170851,"fdc_description":"Cheese, ricotta, whole milk","per_100g":{"calories":174,"protein_g":11.26,"carbs_g":3.04,"fat_g":12.98,"saturated_fat_g":8.295,"fiber_g":0,"sugar_g":0.27,"sodium_mg":84},"source_url":"https://fdc.nal.usda.gov/food-details/170851/nutrients"},{"ingredient":"espinaca cruda","edible_grams":200,"fdc_id":168462,"fdc_description":"Spinach, raw","per_100g":{"calories":23,"protein_g":2.86,"carbs_g":3.63,"fat_g":0.39,"saturated_fat_g":0.063,"fiber_g":2.2,"sugar_g":0.42,"sodium_mg":79},"source_url":"https://fdc.nal.usda.gov/food-details/168462/nutrients"},{"ingredient":"queso parmesano duro","edible_grams":40,"fdc_id":170848,"fdc_description":"Cheese, parmesan, hard","per_100g":{"calories":392,"protein_g":35.75,"carbs_g":3.22,"fat_g":25,"saturated_fat_g":16.41,"fiber_g":0,"sugar_g":0.8,"sodium_mg":1184},"source_url":"https://fdc.nal.usda.gov/food-details/170848/nutrients"},{"ingredient":"mantequilla sin sal","edible_grams":40,"fdc_id":173430,"fdc_description":"Butter, without salt","per_100g":{"sugar_g":0.06,"calories":717,"saturated_fat_g":50.489,"fat_g":81.11,"carbs_g":0.06,"protein_g":0.85,"fiber_g":0,"sodium_mg":11},"source_url":"https://fdc.nal.usda.gov/food-details/173430/nutrients"},{"ingredient":"nuez moscada","edible_grams":0.5,"fdc_id":171326,"fdc_description":"Spices, nutmeg, ground","per_100g":{"protein_g":5.84,"sodium_mg":16,"saturated_fat_g":25.94,"fat_g":36.31,"carbs_g":49.29,"calories":525,"sugar_g":2.99,"fiber_g":20.8},"source_url":"https://fdc.nal.usda.gov/food-details/171326/nutrients"},{"ingredient":"sal de mesa","edible_grams":5,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0,"sodium_mg":38758,"saturated_fat_g":0,"protein_g":0,"fat_g":0,"carbs_g":0,"calories":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"}]},"keywords":["raviolis caseros","raviolis de ricotta y espinaca","masa fresca para ravioli"],"image_url":"/recetas/receta-raviolis-caseros/portada.webp","gallery":[{"url":"/recetas/receta-raviolis-caseros/portada.webp","alt":"Raviolis caseros rellenos de ricotta y espinaca con mantequilla dorada y hojas de salvia"}],"seo":{"title":"Raviolis caseros de ricotta y espinaca","description":"Raviolis caseros de ricotta y espinaca para 4: masa fresca de huevo, sellado paso a paso y acabado de mantequilla con salvia.","image_alt":"Raviolis caseros rellenos de ricotta y espinaca con mantequilla dorada y hojas de salvia","image_variants":["/recetas/receta-raviolis-caseros/portada-1x1.webp","/recetas/receta-raviolis-caseros/portada-4x3.webp","/recetas/receta-raviolis-caseros/portada-16x9.webp"],"faq":[{"q":"¿Por qué se abren los raviolis al cocer?","a":"Suelen abrirse por relleno húmedo, aire atrapado, bordes con harina o un sellado débil. Escurre la ricotta, exprime la espinaca, expulsa el aire y humedece apenas el contorno antes de presionar."},{"q":"¿Puedo hacerlos sin máquina de pasta?","a":"Sí, con rodillo y porciones pequeñas. Busca una lámina uniforme de alrededor de 1 mm y mantén cubierta la masa que no estés estirando. El tiempo puede aumentar respecto de los 90 minutos propuestos."},{"q":"¿Se pueden congelar antes de cocer?","a":"Sí. Congélalos crudos y separados en bandeja, luego pásalos a un recipiente. Cuécelos desde congelados, amplía el tiempo según sea necesario y verifica que el centro alcance al menos 71 °C."}]},"published":false,"editorial_status":"draft","content_html":"<p>Estos raviolis caseros combinan una masa fresca de huevo con un relleno espeso de ricotta, espinaca y parmesano. Se sellan en 24 unidades y se sirven con mantequilla avellanada y salvia, sin ocultar la técnica con una salsa pesada.</p><p>La propuesta rinde 4 porciones de 6 raviolis. Calcula 70 minutos de preparación y 20 de cocción, 90 en total; el escurrido, el reposo y parte de la preparación se solapan. Cantidades, espesor de la masa, tiempos y rendimiento están pendientes de una prueba de cocina.</p>"},{"id":"6360a440-039c-553a-893c-cd6cebe608a5","recipe_group_id":"e8238258-5fe1-4344-8851-917fa546f20b","slug":"hausgemachte-ravioli","public_path":"/de/hausgemachte-ravioli","source_url":null,"language":"de","title":"Hausgemachte Ravioli mit Ricotta und Spinat","excerpt":"Hausgemachte Ricotta-Spinat-Ravioli für 4: frischer Eierteig, sicheres Verschließen und braune Butter mit Salbei.","summary":"Diese hausgemachten Ravioli verbinden frischen Eierteig mit einer festen Füllung aus Ricotta, Spinat und Parmesan. Sie werden zu 24 Stück verschlossen und mit gebräunter Butter und Salbei serviert, ohne die Technik unter einer schweren Sauce zu verstecken.\n\nDer Vorschlag ergibt 4 Portionen mit je 6 Ravioli. Vorgesehen sind 70 Minuten Vorbereitung und 20 Minuten Garen, insgesamt 90; Abtropfen, Ruhen und Teile der Vorbereitung überschneiden sich. Mengen, Teigdicke, Zeiten und Ausbeute sind noch nicht im Küchentest bestätigt.","category":"Pasta","category_slug":"pastas","difficulty":"Mittel","course":"Hauptgericht","cuisine":"Italienisch, Vorschlag für die Hausküche","prep_time_minutes":70,"cook_time_minutes":20,"total_time_minutes":90,"servings":4,"ingredients":[{"name":"Weizenmehl Type 405 oder Allzweckmehl","amount":"320","unit":"g","group":"Teig"},{"name":"Große Eier, ohne Schale","amount":"3","unit":"große Eier (etwa 150 g)","group":"Teig"},{"name":"Wasser","amount":"15","unit":"ml, nur bei Bedarf","group":"Teig"},{"name":"Ricotta aus Vollmilch","amount":"300","unit":"g","group":"Füllung"},{"name":"Frischer Spinat","amount":"200","unit":"g","group":"Füllung"},{"name":"Fein geriebener Parmesan","amount":"40","unit":"g","group":"Füllung"},{"name":"Gemahlene Muskatnuss","amount":"0.5","unit":"g","group":"Füllung"},{"name":"Feines Salz","amount":"5","unit":"g, aufgeteilt"},{"name":"Ungesalzene Butter","amount":"40","unit":"g","group":"Fertigstellung"},{"name":"Frische Salbeiblätter","amount":"6","unit":"g","group":"Fertigstellung"},{"name":"Kochwasser","amount":"3000","unit":"ml","group":"Garen"}],"steps":[{"title":"Ricotta abtropfen lassen","content":"300 g Ricotta in ein feines Sieb über eine Schüssel geben, abdecken und 30 Minuten im Kühlschrank abtropfen lassen. Nicht bei Raumtemperatur stehen lassen. Am Ende sanft drücken, ohne ihn zu einer trockenen Paste zu machen. Diese Wartezeit gehört zu den 70 Minuten Vorbereitung und kann sich mit Teig und Spinat überschneiden.","image_url":"/recetas/receta-raviolis-caseros/paso-01.webp","image_alt":"Hausgemachte Ravioli mit Ricotta und Spinat: Ricotta abtropfen lassen"},{"title":"Spinat garen und trocknen","content":"200 g Spinat waschen und noch feucht in eine breite Pfanne geben. Bei mittlerer Hitze 2–3 Minuten unter Bewegen zusammenfallen lassen. Auf einem sauberen Teller abkühlen lassen; sobald er angefasst werden kann, mit sauberen Händen oder einem sauberen Tuch möglichst viel Wasser ausdrücken und fein hacken. Nasser Spinat kann die Ravioli öffnen.","image_url":"/recetas/receta-raviolis-caseros/paso-02.webp","image_alt":"Hausgemachte Ravioli mit Ricotta und Spinat: Spinat garen und trocknen"},{"title":"Teig mischen","content":"In 300 g Mehl eine Mulde bilden und 3 Eier, etwa 150 g ohne Schale, hineingeben. Eier mit einer Gabel verquirlen und nach und nach Mehl vom Rand einarbeiten. Zu einem festen Teig kneten; Wasser nur in Schritten von 5 ml zufügen, wenn nach mehreren Minuten trockene Stellen bleiben. Die übrigen 20 g Mehl für Arbeitsfläche und Blech reservieren. Die Aufnahme variiert; nicht automatisch das ganze Wasser zufügen.","image_url":"/recetas/receta-raviolis-caseros/paso-03.webp","image_alt":"Hausgemachte Ravioli mit Ricotta und Spinat: Teig mischen"},{"title":"Kneten und ruhen lassen","content":"Auf sauberer Fläche 8–10 Minuten kneten, bis der Teig glatt ist und nach Druck langsam zurückfedert. Gut einwickeln, damit er nicht austrocknet, und 30 Minuten bei kühler Raumtemperatur ruhen lassen. Arbeitsfläche und Geräte mit Kontakt zu rohem Ei reinigen, bevor Füllung oder gegarte Ravioli berührt werden.","image_url":"/recetas/receta-raviolis-caseros/paso-04.webp","image_alt":"Hausgemachte Ravioli mit Ricotta und Spinat: Kneten und ruhen lassen"},{"title":"Eine feste Füllung zubereiten","content":"Abgetropften Ricotta, gehackten Spinat, 40 g Parmesan, 0,5 g Muskat und 2 g Salz mischen. Die Masse soll dick sein und die Form eines Teelöffels halten. Sichtbar in 24 Portionen zu etwa 20 g teilen; wenn sie verläuft oder Flüssigkeit abgibt, 10 Minuten kühlen und erneut prüfen. Dieser Füllungsvorschlag enthält kein Ei.","image_url":"/recetas/receta-raviolis-caseros/paso-05.webp","image_alt":"Hausgemachte Ravioli mit Ricotta und Spinat: Eine feste Füllung zubereiten"},{"title":"Ausrollen, füllen und verschließen","content":"Teig in 4 Teile teilen und 3 eingewickelt lassen. Einen Teil mit Maschine oder Nudelholz gleichmäßig auf etwa 1 mm ausrollen; Löcher vermeiden. 6 Füllungsportionen mit Abstand aufsetzen, den Rand ganz leicht mit Wasser befeuchten und mit der anderen Blatthälfte bedecken. Luft von der Füllung nach außen drücken und fest verschließen. 6 Ravioli schneiden und jeden Rand prüfen. Bis 24 Stück wiederholen; mit etwas reserviertem Mehl ohne Stapeln auf ein Blech legen. Sofort garen oder abgedeckt höchstens vorgeschlagene 2 Stunden vor dem Garen kühlen.","image_url":"/recetas/receta-raviolis-caseros/paso-06.webp","image_alt":"Hausgemachte Ravioli mit Ricotta und Spinat: Ausrollen, füllen und verschließen"},{"title":"Ravioli portionsweise garen","content":"3 Liter Wasser mit den übrigen 3 g Salz aufkochen. Gleichzeitig 40 g Butter bei mittlerer bis kleiner Hitze mit Salbei schmelzen, bis sie nussig riecht und die Milchbestandteile goldbraun, nicht schwarz sind; vom Herd nehmen. Ravioli in 2 Portionen garen, damit sie nicht kleben: vorsichtig rühren und nach erneutem mäßigem Kochen 3–5 Minuten rechnen. Einen Raviolo aus der ersten Portion öffnen: Pasta weich, Rand durchgegart und Mitte mindestens 71 °C. Sonst weitergaren und einen neuen Raviolo prüfen.","image_url":"/recetas/receta-raviolis-caseros/paso-07.webp","image_alt":"Hausgemachte Ravioli mit Ricotta und Spinat: Ravioli portionsweise garen"},{"title":"Fertigstellen, servieren und lagern","content":"Ravioli mit Schaumlöffel herausheben, einige Sekunden abtropfen und in die Pfanne mit Salbeibutter geben. 30–60 Sekunden vorsichtig bewegen, ohne sie zu zerbrechen. Sofort 6 Ravioli pro Person servieren. Reste in flachen Behältern binnen 2 Stunden bei höchstens 4 °C kühlen, bei über 32 °C Raumtemperatur binnen 1 Stunde; Verbrauch innerhalb 2 Tagen wird vorgeschlagen. Nur einmal bis 74 °C im Kern erhitzen. Reste von rohem Ei mit Kontakt zu Mehl oder ungereinigten Geräten nicht aufbewahren.","image_url":"/recetas/receta-raviolis-caseros/paso-08.webp","image_alt":"Hausgemachte Ravioli mit Ricotta und Spinat: Fertigstellen, servieren und lagern"}],"notes":"Teig und Füllung enthalten Weizen, Ei und Milch. Diese Karte schlägt keinen gluten-, ei- oder milchfreien Ersatz vor, weil Hydration, Struktur und Nährwerte sich ändern. Ricotta kalt abtropfen und Spinat gut ausdrücken. Offene Ränder vor dem Garen neu verschließen; Ravioli nicht stapeln. 1 mm Dicke, 24 Stück und Zeiten sind redaktionelle Ziele vor Küchenbestätigung. Zum Einfrieren rohe Ravioli getrennt auf einem Blech fest werden lassen und dann umfüllen; gefroren garen, Zeit verlängern und mindestens 71 °C im Kern prüfen. Nicht bei Raumtemperatur auftauen.","nutrition":{"calories":598.4,"protein_g":26.5,"carbs_g":65.8,"fat_g":24.9,"saturated_fat_g":14.3,"fiber_g":3.3,"sugar_g":0.9,"sodium_mg":761,"estimated":true,"serving_size":"6 Ravioli von vorgeschlagenen 24, mit einem Viertel der Sauce","source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Acht geprüfte SR-Legacy-Datensätze; vorgeschlagene essbare Gewichte addiert und durch 4 geteilt. Alle 320 g Mehl und 40 g Butter werden gerechnet, obwohl Arbeitsmehl oder Sauce zurückbleiben können. Alle 5 g Salz werden konservativ gerechnet, obwohl ein Teil des gesalzenen Kochwassers verworfen wird.","note":"Informationsschätzung, keine Analyse des fertigen Gerichts. Marke und Feuchte des Ricotta, tatsächliche Eiergröße, nicht eingearbeitetes Mehl, aufgenommenes Wasser sowie Käse und Butter an Geräten verändern das Ergebnis. Mengen und Ausbeute warten auf einen Küchentest.","inputs":[{"ingredient":"Weizenmehl Type 405 oder Allzweckmehl","edible_grams":320,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"fiber_g":2.7,"fat_g":0.98,"carbs_g":76.31,"calories":364,"protein_g":10.33,"sodium_mg":2,"saturated_fat_g":0.155,"sugar_g":0.27},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"Große Eier, ohne Schale","edible_grams":150,"fdc_id":171287,"fdc_description":"Egg, whole, raw, fresh","per_100g":{"calories":143,"saturated_fat_g":3.126,"protein_g":12.56,"sodium_mg":142,"sugar_g":0.37,"fat_g":9.51,"carbs_g":0.72,"fiber_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171287/nutrients"},{"ingredient":"Ricotta aus Vollmilch","edible_grams":300,"fdc_id":170851,"fdc_description":"Cheese, ricotta, whole milk","per_100g":{"calories":174,"protein_g":11.26,"carbs_g":3.04,"fat_g":12.98,"saturated_fat_g":8.295,"fiber_g":0,"sugar_g":0.27,"sodium_mg":84},"source_url":"https://fdc.nal.usda.gov/food-details/170851/nutrients"},{"ingredient":"Frischer Spinat","edible_grams":200,"fdc_id":168462,"fdc_description":"Spinach, raw","per_100g":{"calories":23,"protein_g":2.86,"carbs_g":3.63,"fat_g":0.39,"saturated_fat_g":0.063,"fiber_g":2.2,"sugar_g":0.42,"sodium_mg":79},"source_url":"https://fdc.nal.usda.gov/food-details/168462/nutrients"},{"ingredient":"Fein geriebener Parmesan","edible_grams":40,"fdc_id":170848,"fdc_description":"Cheese, parmesan, hard","per_100g":{"calories":392,"protein_g":35.75,"carbs_g":3.22,"fat_g":25,"saturated_fat_g":16.41,"fiber_g":0,"sugar_g":0.8,"sodium_mg":1184},"source_url":"https://fdc.nal.usda.gov/food-details/170848/nutrients"},{"ingredient":"Ungesalzene Butter","edible_grams":40,"fdc_id":173430,"fdc_description":"Butter, without salt","per_100g":{"sugar_g":0.06,"calories":717,"saturated_fat_g":50.489,"fat_g":81.11,"carbs_g":0.06,"protein_g":0.85,"fiber_g":0,"sodium_mg":11},"source_url":"https://fdc.nal.usda.gov/food-details/173430/nutrients"},{"ingredient":"Gemahlene Muskatnuss","edible_grams":0.5,"fdc_id":171326,"fdc_description":"Spices, nutmeg, ground","per_100g":{"protein_g":5.84,"sodium_mg":16,"saturated_fat_g":25.94,"fat_g":36.31,"carbs_g":49.29,"calories":525,"sugar_g":2.99,"fiber_g":20.8},"source_url":"https://fdc.nal.usda.gov/food-details/171326/nutrients"},{"ingredient":"Feines Salz","edible_grams":5,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0,"sodium_mg":38758,"saturated_fat_g":0,"protein_g":0,"fat_g":0,"carbs_g":0,"calories":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"}]},"keywords":["hausgemachte Ravioli","Ricotta-Spinat-Ravioli","frischer Ravioliteig"],"image_url":"/recetas/receta-raviolis-caseros/portada.webp","gallery":[{"url":"/recetas/receta-raviolis-caseros/portada.webp","alt":"Hausgemachte Ricotta-Spinat-Ravioli mit brauner Butter und Salbeiblättern"}],"seo":{"title":"Hausgemachte Ravioli mit Ricotta und Spinat","description":"Hausgemachte Ricotta-Spinat-Ravioli für 4: frischer Eierteig, sicheres Verschließen und braune Butter mit Salbei.","image_alt":"Hausgemachte Ricotta-Spinat-Ravioli mit brauner Butter und Salbeiblättern","image_variants":["/recetas/receta-raviolis-caseros/portada-1x1.webp","/recetas/receta-raviolis-caseros/portada-4x3.webp","/recetas/receta-raviolis-caseros/portada-16x9.webp"],"faq":[{"q":"Warum öffnen sich Ravioli beim Garen?","a":"Häufige Ursachen sind feuchte Füllung, eingeschlossene Luft, Mehl am Rand oder ein schwacher Verschluss. Ricotta abtropfen, Spinat ausdrücken, Luft herausdrücken und den Rand vor dem Pressen nur leicht befeuchten."},{"q":"Geht es ohne Pastamaschine?","a":"Ja, mit Nudelholz und kleinen Teigportionen. Ein gleichmäßiges Blatt von etwa 1 mm anstreben und unbenutzten Teig abdecken. Die Arbeit kann länger als die vorgeschlagenen 90 Minuten dauern."},{"q":"Kann ich sie vor dem Garen einfrieren?","a":"Ja. Rohe Ravioli getrennt auf einem Blech einfrieren und dann umfüllen. Gefroren garen, Zeit nach Bedarf verlängern und mindestens 71 °C im Kern prüfen."}]},"published":false,"editorial_status":"draft","content_html":"<p>Diese hausgemachten Ravioli verbinden frischen Eierteig mit einer festen Füllung aus Ricotta, Spinat und Parmesan. Sie werden zu 24 Stück verschlossen und mit gebräunter Butter und Salbei serviert, ohne die Technik unter einer schweren Sauce zu verstecken.</p><p>Der Vorschlag ergibt 4 Portionen mit je 6 Ravioli. Vorgesehen sind 70 Minuten Vorbereitung und 20 Minuten Garen, insgesamt 90; Abtropfen, Ruhen und Teile der Vorbereitung überschneiden sich. Mengen, Teigdicke, Zeiten und Ausbeute sind noch nicht im Küchentest bestätigt.</p>"},{"id":"b78e6eeb-3922-546b-ace2-18727865a6a5","recipe_group_id":"e8238258-5fe1-4344-8851-917fa546f20b","slug":"homemade-ravioli","public_path":"/en/homemade-ravioli","source_url":null,"language":"en","title":"Homemade ricotta and spinach ravioli","excerpt":"Homemade ricotta and spinach ravioli for 4: fresh egg pasta, step-by-step sealing and a brown-butter sage finish.","summary":"These homemade ravioli pair fresh egg pasta with a thick ricotta, spinach and Parmesan filling. They are sealed into 24 pieces and served with brown butter and sage, without hiding the technique under a heavy sauce.\n\nThe proposal makes 4 servings of 6 ravioli. Allow 70 minutes for preparation and 20 for cooking, 90 in total; draining, resting and part of the preparation overlap. Quantities, dough thickness, times and yield await a kitchen test.","category":"Pasta","category_slug":"pastas","difficulty":"Medium","course":"Main course","cuisine":"Italian, home-style proposal","prep_time_minutes":70,"cook_time_minutes":20,"total_time_minutes":90,"servings":4,"ingredients":[{"name":"All-purpose wheat flour","amount":"320","unit":"g","group":"Dough"},{"name":"Large eggs, without shells","amount":"3","unit":"large eggs (about 150 g)","group":"Dough"},{"name":"Water","amount":"15","unit":"ml, only if needed","group":"Dough"},{"name":"Whole-milk ricotta","amount":"300","unit":"g","group":"Filling"},{"name":"Fresh spinach","amount":"200","unit":"g","group":"Filling"},{"name":"Finely grated Parmesan cheese","amount":"40","unit":"g","group":"Filling"},{"name":"Ground nutmeg","amount":"0.5","unit":"g","group":"Filling"},{"name":"Fine salt","amount":"5","unit":"g, divided"},{"name":"Unsalted butter","amount":"40","unit":"g","group":"Finishing"},{"name":"Fresh sage leaves","amount":"6","unit":"g","group":"Finishing"},{"name":"Cooking water","amount":"3000","unit":"ml","group":"Cooking"}],"steps":[{"title":"Drain the ricotta","content":"Put the 300 g ricotta in a fine strainer over a bowl, cover and drain for 30 minutes in the refrigerator. Do not leave it at room temperature. Press gently at the end without turning it into a dry paste. This wait is included in the 70-minute preparation time and can overlap with making the dough and spinach.","image_url":"/recetas/receta-raviolis-caseros/paso-01.webp","image_alt":"Homemade ricotta and spinach ravioli: Drain the ricotta"},{"title":"Cook and dry the spinach","content":"Wash the 200 g spinach and put it, still damp, in a wide skillet. Cook over medium heat for 2–3 minutes, stirring, until wilted. Spread it on a clean plate to lose heat; once safe to handle, squeeze it with clean hands or a clean cloth to remove as much water as possible, then chop finely. Wet spinach can open the ravioli.","image_url":"/recetas/receta-raviolis-caseros/paso-02.webp","image_alt":"Homemade ricotta and spinach ravioli: Cook and dry the spinach"},{"title":"Mix the dough","content":"Make a well in 300 g of the flour and add the 3 eggs, about 150 g without shells. Beat the eggs with a fork and gradually draw in flour from the edge. Knead until a firm dough comes together; add water 5 ml at a time only if dry pieces remain after several minutes. Reserve the remaining 20 g flour for the worktop and tray. Absorption varies, so do not add all the water automatically.","image_url":"/recetas/receta-raviolis-caseros/paso-03.webp","image_alt":"Homemade ricotta and spinach ravioli: Mix the dough"},{"title":"Knead and rest","content":"Knead for 8–10 minutes on a clean surface until the dough looks smooth and slowly springs back when pressed. Wrap well so it does not dry out and rest for 30 minutes at cool room temperature. Clean the worktop and tools that touched raw egg before preparing the filling or handling cooked ravioli.","image_url":"/recetas/receta-raviolis-caseros/paso-04.webp","image_alt":"Homemade ricotta and spinach ravioli: Knead and rest"},{"title":"Make a dry filling","content":"Mix the drained ricotta, chopped spinach, 40 g Parmesan, 0.5 g nutmeg and 2 g of the salt. It should be thick enough to hold the shape of a teaspoon. Visually divide it into 24 portions of about 20 g; if it spreads or releases liquid, refrigerate for 10 minutes and check again. Do not add egg to this proposed filling.","image_url":"/recetas/receta-raviolis-caseros/paso-05.webp","image_alt":"Homemade ricotta and spinach ravioli: Make a dry filling"},{"title":"Roll, fill and seal","content":"Divide the dough into 4 pieces and keep 3 wrapped. Roll one piece by machine or rolling pin to an even sheet about 1 mm thick; avoid holes. Place 6 filling portions apart, barely moisten the outline with water and cover with the other half of the sheet. Press air away from the filling and seal firmly. Cut 6 ravioli and check every edge. Repeat to make 24; place on a tray with some reserved flour, without stacking. Cook immediately or refrigerate covered for a proposed maximum of 2 hours before cooking.","image_url":"/recetas/receta-raviolis-caseros/paso-06.webp","image_alt":"Homemade ricotta and spinach ravioli: Roll, fill and seal"},{"title":"Cook the ravioli in batches","content":"Boil the 3 litres of water with the remaining 3 g salt. Meanwhile, melt the 40 g butter over medium-low heat with the sage leaves until it smells nutty and the milk solids are golden, not black; remove from the heat. Cook the ravioli in 2 batches so they do not stick: stir gently and allow 3–5 minutes after the water returns to a moderate boil. Open one test ravioli from the first batch: pasta should be tender, the seal cooked and the centre at least 71 °C. If not, continue and test another ravioli.","image_url":"/recetas/receta-raviolis-caseros/paso-07.webp","image_alt":"Homemade ricotta and spinach ravioli: Cook the ravioli in batches"},{"title":"Finish, serve and store","content":"Lift out the ravioli with a slotted spoon, drain for a few seconds and transfer to the sage butter skillet. Move gently for 30–60 seconds to coat without breaking. Serve 6 ravioli per person immediately. Refrigerate leftovers in shallow containers at 4 °C or below within 2 hours, or 1 hour if the room exceeds 32 °C; using them within 2 days is proposed. Reheat only once to 74 °C at the centre. Do not keep leftover raw egg that contacted flour or unsanitized tools.","image_url":"/recetas/receta-raviolis-caseros/paso-08.webp","image_alt":"Homemade ricotta and spinach ravioli: Finish, serve and store"}],"notes":"The dough and filling contain wheat, egg and milk. This card does not propose gluten-free, egg-free or dairy-free substitutions because they would change hydration, structure and nutrition. Drain ricotta cold and squeeze spinach thoroughly. Reseal any open edge before cooking and do not stack the ravioli. The 1 mm thickness, 24-piece yield and times are editorial targets awaiting kitchen confirmation. To freeze, arrange raw ravioli separately on a tray until firm, then transfer to a container; cook from frozen, add time as needed and verify at least 71 °C in the centre. Do not thaw at room temperature.","nutrition":{"calories":598.4,"protein_g":26.5,"carbs_g":65.8,"fat_g":24.9,"saturated_fat_g":14.3,"fiber_g":3.3,"sugar_g":0.9,"sodium_mg":761,"estimated":true,"serving_size":"6 ravioli out of a proposed total of 24, with one quarter of the sauce","source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Eight verified SR Legacy records; proposed edible weights added and divided by 4. All 320 g flour and 40 g butter are counted, although worktop flour or sauce may remain. All 5 g salt are counted conservatively even though some salted cooking water is discarded.","note":"Informational estimate, not analysis of the finished dish. Ricotta brand and moisture, actual egg size, unincorporated flour, absorbed water, cheese and butter left on utensils change the result. Quantities and yield await a kitchen test.","inputs":[{"ingredient":"All-purpose wheat flour","edible_grams":320,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"fiber_g":2.7,"fat_g":0.98,"carbs_g":76.31,"calories":364,"protein_g":10.33,"sodium_mg":2,"saturated_fat_g":0.155,"sugar_g":0.27},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"Large eggs, without shells","edible_grams":150,"fdc_id":171287,"fdc_description":"Egg, whole, raw, fresh","per_100g":{"calories":143,"saturated_fat_g":3.126,"protein_g":12.56,"sodium_mg":142,"sugar_g":0.37,"fat_g":9.51,"carbs_g":0.72,"fiber_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171287/nutrients"},{"ingredient":"Whole-milk ricotta","edible_grams":300,"fdc_id":170851,"fdc_description":"Cheese, ricotta, whole milk","per_100g":{"calories":174,"protein_g":11.26,"carbs_g":3.04,"fat_g":12.98,"saturated_fat_g":8.295,"fiber_g":0,"sugar_g":0.27,"sodium_mg":84},"source_url":"https://fdc.nal.usda.gov/food-details/170851/nutrients"},{"ingredient":"Fresh spinach","edible_grams":200,"fdc_id":168462,"fdc_description":"Spinach, raw","per_100g":{"calories":23,"protein_g":2.86,"carbs_g":3.63,"fat_g":0.39,"saturated_fat_g":0.063,"fiber_g":2.2,"sugar_g":0.42,"sodium_mg":79},"source_url":"https://fdc.nal.usda.gov/food-details/168462/nutrients"},{"ingredient":"Finely grated Parmesan cheese","edible_grams":40,"fdc_id":170848,"fdc_description":"Cheese, parmesan, hard","per_100g":{"calories":392,"protein_g":35.75,"carbs_g":3.22,"fat_g":25,"saturated_fat_g":16.41,"fiber_g":0,"sugar_g":0.8,"sodium_mg":1184},"source_url":"https://fdc.nal.usda.gov/food-details/170848/nutrients"},{"ingredient":"Unsalted butter","edible_grams":40,"fdc_id":173430,"fdc_description":"Butter, without salt","per_100g":{"sugar_g":0.06,"calories":717,"saturated_fat_g":50.489,"fat_g":81.11,"carbs_g":0.06,"protein_g":0.85,"fiber_g":0,"sodium_mg":11},"source_url":"https://fdc.nal.usda.gov/food-details/173430/nutrients"},{"ingredient":"Ground nutmeg","edible_grams":0.5,"fdc_id":171326,"fdc_description":"Spices, nutmeg, ground","per_100g":{"protein_g":5.84,"sodium_mg":16,"saturated_fat_g":25.94,"fat_g":36.31,"carbs_g":49.29,"calories":525,"sugar_g":2.99,"fiber_g":20.8},"source_url":"https://fdc.nal.usda.gov/food-details/171326/nutrients"},{"ingredient":"Fine salt","edible_grams":5,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0,"sodium_mg":38758,"saturated_fat_g":0,"protein_g":0,"fat_g":0,"carbs_g":0,"calories":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"}]},"keywords":["homemade ravioli","ricotta spinach ravioli","fresh ravioli dough"],"image_url":"/recetas/receta-raviolis-caseros/portada.webp","gallery":[{"url":"/recetas/receta-raviolis-caseros/portada.webp","alt":"Homemade ricotta and spinach ravioli with brown butter and sage leaves"}],"seo":{"title":"Homemade ricotta and spinach ravioli","description":"Homemade ricotta and spinach ravioli for 4: fresh egg pasta, step-by-step sealing and a brown-butter sage finish.","image_alt":"Homemade ricotta and spinach ravioli with brown butter and sage leaves","image_variants":["/recetas/receta-raviolis-caseros/portada-1x1.webp","/recetas/receta-raviolis-caseros/portada-4x3.webp","/recetas/receta-raviolis-caseros/portada-16x9.webp"],"faq":[{"q":"Why do ravioli open while cooking?","a":"Common causes are wet filling, trapped air, flour on the edges or a weak seal. Drain the ricotta, squeeze the spinach, push out the air and barely moisten the outline before pressing."},{"q":"Can I make them without a pasta machine?","a":"Yes, with a rolling pin and small dough portions. Aim for an even sheet about 1 mm thick and keep unused dough covered. The work may take longer than the proposed 90 minutes."},{"q":"Can I freeze them before cooking?","a":"Yes. Freeze raw ravioli separately on a tray, then transfer them to a container. Cook from frozen, extend the time as needed and verify that the centre reaches at least 71 °C."}]},"published":false,"editorial_status":"draft","content_html":"<p>These homemade ravioli pair fresh egg pasta with a thick ricotta, spinach and Parmesan filling. They are sealed into 24 pieces and served with brown butter and sage, without hiding the technique under a heavy sauce.</p><p>The proposal makes 4 servings of 6 ravioli. Allow 70 minutes for preparation and 20 for cooking, 90 in total; draining, resting and part of the preparation overlap. Quantities, dough thickness, times and yield await a kitchen test.</p>"},{"id":"31fb01d4-8b3c-5723-aeb4-50b7f722d0e4","recipe_group_id":"e8238258-5fe1-4344-8851-917fa546f20b","slug":"raviolis-maison","public_path":"/fr/raviolis-maison","source_url":null,"language":"fr","title":"Raviolis maison à la ricotta et aux épinards","excerpt":"Raviolis maison ricotta-épinards pour 4 : pâte fraîche aux œufs, fermeture détaillée et beurre noisette à la sauge.","summary":"Ces raviolis maison associent une pâte fraîche aux œufs à une farce épaisse de ricotta, épinards et parmesan. Ils sont fermés en 24 pièces et servis avec un beurre noisette à la sauge, sans masquer la technique sous une sauce lourde.\n\nLa proposition donne 4 portions de 6 raviolis. Comptez 70 minutes de préparation et 20 de cuisson, 90 au total ; égouttage, repos et certaines préparations se chevauchent. Quantités, épaisseur, durées et rendement attendent un essai en cuisine.","category":"Pâtes","category_slug":"pastas","difficulty":"Moyenne","course":"Plat principal","cuisine":"Italienne, proposition maison","prep_time_minutes":70,"cook_time_minutes":20,"total_time_minutes":90,"servings":4,"ingredients":[{"name":"Farine de blé tout usage","amount":"320","unit":"g","group":"Pâte"},{"name":"Gros œufs, sans coquille","amount":"3","unit":"gros œufs (environ 150 g)","group":"Pâte"},{"name":"Eau","amount":"15","unit":"ml, seulement si nécessaire","group":"Pâte"},{"name":"Ricotta au lait entier","amount":"300","unit":"g","group":"Farce"},{"name":"Épinards frais","amount":"200","unit":"g","group":"Farce"},{"name":"Parmesan finement râpé","amount":"40","unit":"g","group":"Farce"},{"name":"Muscade moulue","amount":"0.5","unit":"g","group":"Farce"},{"name":"Sel fin","amount":"5","unit":"g, répartis"},{"name":"Beurre doux","amount":"40","unit":"g","group":"Finition"},{"name":"Feuilles de sauge fraîche","amount":"6","unit":"g","group":"Finition"},{"name":"Eau de cuisson","amount":"3000","unit":"ml","group":"Cuisson"}],"steps":[{"title":"Égoutter la ricotta","content":"Mettez les 300 g de ricotta dans une passoire fine au-dessus d’un bol, couvrez et laissez égoutter 30 minutes au réfrigérateur. Ne la laissez pas à température ambiante. Pressez doucement à la fin sans en faire une pâte sèche. Cette attente est comprise dans les 70 minutes de préparation et peut chevaucher la pâte et les épinards.","image_url":"/recetas/receta-raviolis-caseros/paso-01.webp","image_alt":"Raviolis maison à la ricotta et aux épinards: Égoutter la ricotta"},{"title":"Cuire et sécher les épinards","content":"Lavez les 200 g d’épinards et mettez-les encore humides dans une grande poêle. Cuisez 2–3 minutes à feu moyen en remuant, jusqu’à ce qu’ils tombent. Étalez sur une assiette propre pour refroidir ; dès qu’ils sont manipulables, pressez avec des mains propres ou un linge propre pour retirer le plus d’eau possible, puis hachez finement. Des épinards humides peuvent ouvrir les raviolis.","image_url":"/recetas/receta-raviolis-caseros/paso-02.webp","image_alt":"Raviolis maison à la ricotta et aux épinards: Cuire et sécher les épinards"},{"title":"Mélanger la pâte","content":"Creusez un puits dans 300 g de farine et ajoutez les 3 œufs, environ 150 g sans coquille. Battez à la fourchette en incorporant peu à peu la farine du bord. Pétrissez jusqu’à obtenir une pâte ferme ; ajoutez l’eau par 5 ml seulement si des zones sèches subsistent après plusieurs minutes. Réservez les 20 g de farine restants pour le plan et la plaque. L’absorption varie : n’ajoutez pas toute l’eau automatiquement.","image_url":"/recetas/receta-raviolis-caseros/paso-03.webp","image_alt":"Raviolis maison à la ricotta et aux épinards: Mélanger la pâte"},{"title":"Pétrir et laisser reposer","content":"Pétrissez 8–10 minutes sur une surface propre jusqu’à ce que la pâte soit lisse et reprenne lentement sa forme sous la pression. Emballez bien pour éviter le dessèchement et laissez reposer 30 minutes à température ambiante fraîche. Nettoyez plan et ustensiles ayant touché l’œuf cru avant la farce ou les raviolis cuits.","image_url":"/recetas/receta-raviolis-caseros/paso-04.webp","image_alt":"Raviolis maison à la ricotta et aux épinards: Pétrir et laisser reposer"},{"title":"Préparer une farce ferme","content":"Mélangez ricotta égouttée, épinards hachés, 40 g de parmesan, 0,5 g de muscade et 2 g de sel. La farce doit être épaisse et garder la forme d’une cuillerée. Divisez visuellement en 24 portions d’environ 20 g ; si elle s’étale ou rend du liquide, réfrigérez 10 minutes et vérifiez encore. N’ajoutez pas d’œuf à cette farce proposée.","image_url":"/recetas/receta-raviolis-caseros/paso-05.webp","image_alt":"Raviolis maison à la ricotta et aux épinards: Préparer une farce ferme"},{"title":"Abaisser, farcir et fermer","content":"Divisez la pâte en 4 et gardez 3 morceaux emballés. Abaissez-en un à la machine ou au rouleau jusqu’à environ 1 mm, sans trous. Posez 6 portions espacées, humidifiez à peine le contour et couvrez de l’autre moitié. Chassez l’air de la farce vers l’extérieur et pressez pour fermer. Découpez 6 raviolis et vérifiez chaque bord. Répétez jusqu’à 24 ; posez sans empiler sur une plaque avec un peu de farine réservée. Cuisez aussitôt ou réfrigérez couverts pendant un maximum proposé de 2 heures avant cuisson.","image_url":"/recetas/receta-raviolis-caseros/paso-06.webp","image_alt":"Raviolis maison à la ricotta et aux épinards: Abaisser, farcir et fermer"},{"title":"Cuire les raviolis par lots","content":"Faites bouillir les 3 litres d’eau avec les 3 g de sel restants. En parallèle, faites fondre les 40 g de beurre à feu moyen-doux avec la sauge jusqu’à odeur de noisette et solides dorés, non noirs ; retirez du feu. Cuisez en 2 lots pour éviter qu’ils collent : remuez doucement et comptez 3–5 minutes après reprise d’une ébullition modérée. Ouvrez un ravioli test du premier lot : pâte tendre, joint cuit et centre à au moins 71 °C. Sinon, prolongez et testez-en un autre.","image_url":"/recetas/receta-raviolis-caseros/paso-07.webp","image_alt":"Raviolis maison à la ricotta et aux épinards: Cuire les raviolis par lots"},{"title":"Finir, servir et conserver","content":"Sortez avec une écumoire, égouttez quelques secondes et passez dans le beurre à la sauge. Remuez délicatement 30–60 secondes sans casser. Servez aussitôt 6 raviolis par personne. Réfrigérez les restes en contenants peu profonds à 4 °C ou moins dans les 2 heures, ou 1 heure si la pièce dépasse 32 °C ; consommation proposée sous 2 jours. Réchauffez une seule fois jusqu’à 74 °C au centre. Ne gardez pas d’œuf cru restant ayant touché farine ou matériel non assaini.","image_url":"/recetas/receta-raviolis-caseros/paso-08.webp","image_alt":"Raviolis maison à la ricotta et aux épinards: Finir, servir et conserver"}],"notes":"Pâte et farce contiennent blé, œuf et lait. Cette fiche ne propose pas de substitutions sans gluten, sans œuf ou sans lait car elles changeraient hydratation, structure et nutrition. Égouttez la ricotta au froid et pressez bien les épinards. Refermez tout bord ouvert avant cuisson et n’empilez pas. Épaisseur de 1 mm, rendement de 24 pièces et temps sont des objectifs éditoriaux à confirmer en cuisine. Pour congeler, séparez les raviolis crus sur plaque jusqu’à fermeté puis transférez ; cuisez congelés, prolongez au besoin et vérifiez au moins 71 °C au centre. Ne décongelez pas à température ambiante.","nutrition":{"calories":598.4,"protein_g":26.5,"carbs_g":65.8,"fat_g":24.9,"saturated_fat_g":14.3,"fiber_g":3.3,"sugar_g":0.9,"sodium_mg":761,"estimated":true,"serving_size":"6 raviolis sur un total proposé de 24, avec un quart de la sauce","source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Huit fiches SR Legacy vérifiées ; poids comestibles proposés additionnés puis divisés par 4. Les 320 g de farine et 40 g de beurre sont comptés entièrement, même si farine de travail ou sauce restent. Les 5 g de sel sont comptés prudemment bien qu’une partie de l’eau salée soit jetée.","note":"Estimation informative, pas une analyse du plat fini. Marque et humidité de la ricotta, taille réelle des œufs, farine non incorporée, eau absorbée, fromage et beurre restant sur les ustensiles modifient le résultat. Quantités et rendement attendent un essai en cuisine.","inputs":[{"ingredient":"Farine de blé tout usage","edible_grams":320,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"fiber_g":2.7,"fat_g":0.98,"carbs_g":76.31,"calories":364,"protein_g":10.33,"sodium_mg":2,"saturated_fat_g":0.155,"sugar_g":0.27},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"Gros œufs, sans coquille","edible_grams":150,"fdc_id":171287,"fdc_description":"Egg, whole, raw, fresh","per_100g":{"calories":143,"saturated_fat_g":3.126,"protein_g":12.56,"sodium_mg":142,"sugar_g":0.37,"fat_g":9.51,"carbs_g":0.72,"fiber_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171287/nutrients"},{"ingredient":"Ricotta au lait entier","edible_grams":300,"fdc_id":170851,"fdc_description":"Cheese, ricotta, whole milk","per_100g":{"calories":174,"protein_g":11.26,"carbs_g":3.04,"fat_g":12.98,"saturated_fat_g":8.295,"fiber_g":0,"sugar_g":0.27,"sodium_mg":84},"source_url":"https://fdc.nal.usda.gov/food-details/170851/nutrients"},{"ingredient":"Épinards frais","edible_grams":200,"fdc_id":168462,"fdc_description":"Spinach, raw","per_100g":{"calories":23,"protein_g":2.86,"carbs_g":3.63,"fat_g":0.39,"saturated_fat_g":0.063,"fiber_g":2.2,"sugar_g":0.42,"sodium_mg":79},"source_url":"https://fdc.nal.usda.gov/food-details/168462/nutrients"},{"ingredient":"Parmesan finement râpé","edible_grams":40,"fdc_id":170848,"fdc_description":"Cheese, parmesan, hard","per_100g":{"calories":392,"protein_g":35.75,"carbs_g":3.22,"fat_g":25,"saturated_fat_g":16.41,"fiber_g":0,"sugar_g":0.8,"sodium_mg":1184},"source_url":"https://fdc.nal.usda.gov/food-details/170848/nutrients"},{"ingredient":"Beurre doux","edible_grams":40,"fdc_id":173430,"fdc_description":"Butter, without salt","per_100g":{"sugar_g":0.06,"calories":717,"saturated_fat_g":50.489,"fat_g":81.11,"carbs_g":0.06,"protein_g":0.85,"fiber_g":0,"sodium_mg":11},"source_url":"https://fdc.nal.usda.gov/food-details/173430/nutrients"},{"ingredient":"Muscade moulue","edible_grams":0.5,"fdc_id":171326,"fdc_description":"Spices, nutmeg, ground","per_100g":{"protein_g":5.84,"sodium_mg":16,"saturated_fat_g":25.94,"fat_g":36.31,"carbs_g":49.29,"calories":525,"sugar_g":2.99,"fiber_g":20.8},"source_url":"https://fdc.nal.usda.gov/food-details/171326/nutrients"},{"ingredient":"Sel fin","edible_grams":5,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0,"sodium_mg":38758,"saturated_fat_g":0,"protein_g":0,"fat_g":0,"carbs_g":0,"calories":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"}]},"keywords":["raviolis maison","raviolis ricotta épinards","pâte fraîche à raviolis"],"image_url":"/recetas/receta-raviolis-caseros/portada.webp","gallery":[{"url":"/recetas/receta-raviolis-caseros/portada.webp","alt":"Raviolis maison ricotta-épinards avec beurre noisette et feuilles de sauge"}],"seo":{"title":"Raviolis maison à la ricotta et aux épinards","description":"Raviolis maison ricotta-épinards pour 4 : pâte fraîche aux œufs, fermeture détaillée et beurre noisette à la sauge.","image_alt":"Raviolis maison ricotta-épinards avec beurre noisette et feuilles de sauge","image_variants":["/recetas/receta-raviolis-caseros/portada-1x1.webp","/recetas/receta-raviolis-caseros/portada-4x3.webp","/recetas/receta-raviolis-caseros/portada-16x9.webp"],"faq":[{"q":"Pourquoi les raviolis s’ouvrent-ils à la cuisson ?","a":"Une farce humide, de l’air enfermé, de la farine sur les bords ou une fermeture faible sont fréquents. Égouttez la ricotta, pressez les épinards, chassez l’air et humidifiez à peine le contour avant de presser."},{"q":"Puis-je les faire sans machine à pâtes ?","a":"Oui, au rouleau avec de petites portions. Visez une feuille régulière d’environ 1 mm et gardez la pâte inutilisée couverte. Le travail peut dépasser les 90 minutes proposées."},{"q":"Puis-je les congeler avant cuisson ?","a":"Oui. Congelez les raviolis crus séparés sur une plaque puis transférez-les. Cuisez sans décongeler, prolongez au besoin et vérifiez au moins 71 °C au centre."}]},"published":false,"editorial_status":"draft","content_html":"<p>Ces raviolis maison associent une pâte fraîche aux œufs à une farce épaisse de ricotta, épinards et parmesan. Ils sont fermés en 24 pièces et servis avec un beurre noisette à la sauge, sans masquer la technique sous une sauce lourde.</p><p>La proposition donne 4 portions de 6 raviolis. Comptez 70 minutes de préparation et 20 de cuisson, 90 au total ; égouttage, repos et certaines préparations se chevauchent. Quantités, épaisseur, durées et rendement attendent un essai en cuisine.</p>"},{"id":"67dd9ccd-e298-5257-8a97-6419c11ce270","recipe_group_id":"e8238258-5fe1-4344-8851-917fa546f20b","slug":"ravioli-fatti-in-casa","public_path":"/it/ravioli-fatti-in-casa","source_url":null,"language":"it","title":"Ravioli fatti in casa con ricotta e spinaci","excerpt":"Ravioli ricotta e spinaci per 4: pasta fresca all’uovo, chiusura passo passo e burro nocciola alla salvia.","summary":"Questi ravioli fatti in casa uniscono pasta fresca all’uovo e un ripieno sodo di ricotta, spinaci e parmigiano. Si chiudono in 24 pezzi e si servono con burro nocciola e salvia, senza coprire la tecnica con una salsa pesante.\n\nLa proposta rende 4 porzioni da 6 ravioli. Calcola 70 minuti di preparazione e 20 di cottura, 90 in totale; sgocciolatura, riposo e parte del lavoro si sovrappongono. Quantità, spessore, tempi e resa attendono una prova in cucina.","category":"Pasta","category_slug":"pastas","difficulty":"Media","course":"Piatto principale","cuisine":"Italiana, proposta casalinga","prep_time_minutes":70,"cook_time_minutes":20,"total_time_minutes":90,"servings":4,"ingredients":[{"name":"Farina di grano tenero per tutti gli usi","amount":"320","unit":"g","group":"Impasto"},{"name":"Uova grandi, senza guscio","amount":"3","unit":"uova grandi (circa 150 g)","group":"Impasto"},{"name":"Acqua","amount":"15","unit":"ml, solo se necessario","group":"Impasto"},{"name":"Ricotta di latte intero","amount":"300","unit":"g","group":"Ripieno"},{"name":"Spinaci freschi","amount":"200","unit":"g","group":"Ripieno"},{"name":"Parmigiano grattugiato fine","amount":"40","unit":"g","group":"Ripieno"},{"name":"Noce moscata macinata","amount":"0.5","unit":"g","group":"Ripieno"},{"name":"Sale fino","amount":"5","unit":"g, divisi"},{"name":"Burro non salato","amount":"40","unit":"g","group":"Finitura"},{"name":"Foglie di salvia fresca","amount":"6","unit":"g","group":"Finitura"},{"name":"Acqua di cottura","amount":"3000","unit":"ml","group":"Cottura"}],"steps":[{"title":"Fai sgocciolare la ricotta","content":"Metti i 300 g di ricotta in un colino fine sopra una ciotola, copri e lascia sgocciolare 30 minuti in frigorifero. Non lasciarla a temperatura ambiente. Alla fine premi delicatamente senza ridurla a pasta asciutta. L’attesa rientra nei 70 minuti di preparazione e può sovrapporsi a impasto e spinaci.","image_url":"/recetas/receta-raviolis-caseros/paso-01.webp","image_alt":"Ravioli fatti in casa con ricotta e spinaci: Fai sgocciolare la ricotta"},{"title":"Cuoci e asciuga gli spinaci","content":"Lava i 200 g di spinaci e mettili ancora umidi in una padella ampia. Cuoci 2–3 minuti a fuoco medio, muovendo, finché appassiscono. Stendili su un piatto pulito per farli raffreddare; quando si possono toccare, strizzali con mani pulite o un panno pulito per eliminare più acqua possibile, poi tritali fini. Spinaci umidi possono aprire i ravioli.","image_url":"/recetas/receta-raviolis-caseros/paso-02.webp","image_alt":"Ravioli fatti in casa con ricotta e spinaci: Cuoci e asciuga gli spinaci"},{"title":"Mescola l’impasto","content":"Crea una fontana in 300 g di farina e aggiungi le 3 uova, circa 150 g senza guscio. Sbatti con la forchetta incorporando poco a poco farina dal bordo. Impasta fino a riunire un composto sodo; aggiungi acqua 5 ml per volta solo se dopo vari minuti restano parti secche. Conserva i 20 g di farina restanti per piano e vassoio. L’assorbimento varia: non aggiungere tutta l’acqua automaticamente.","image_url":"/recetas/receta-raviolis-caseros/paso-03.webp","image_alt":"Ravioli fatti in casa con ricotta e spinaci: Mescola l’impasto"},{"title":"Impasta e fai riposare","content":"Impasta 8–10 minuti su una superficie pulita finché la pasta è liscia e torna lentamente in forma dopo la pressione. Avvolgi bene per non farla seccare e lascia riposare 30 minuti a temperatura ambiente fresca. Pulisci piano e utensili che hanno toccato uovo crudo prima di fare il ripieno o toccare ravioli cotti.","image_url":"/recetas/receta-raviolis-caseros/paso-04.webp","image_alt":"Ravioli fatti in casa con ricotta e spinaci: Impasta e fai riposare"},{"title":"Prepara un ripieno asciutto","content":"Mescola ricotta sgocciolata, spinaci tritati, 40 g di parmigiano, 0,5 g di noce moscata e 2 g di sale. Deve essere denso e mantenere la forma di un cucchiaino. Dividi visivamente in 24 porzioni da circa 20 g; se si allarga o rilascia liquido, refrigera 10 minuti e ricontrolla. Non aggiungere uovo a questo ripieno proposto.","image_url":"/recetas/receta-raviolis-caseros/paso-05.webp","image_alt":"Ravioli fatti in casa con ricotta e spinaci: Prepara un ripieno asciutto"},{"title":"Stendi, farcisci e sigilla","content":"Dividi l’impasto in 4 parti e tienine 3 avvolte. Stendi una parte a macchina o mattarello fino a circa 1 mm, senza buchi. Disponi 6 porzioni distanziate, inumidisci appena il contorno e copri con l’altra metà della sfoglia. Spingi fuori l’aria e premi per sigillare. Taglia 6 ravioli e controlla ogni bordo. Ripeti fino a 24; metti senza sovrapporre su un vassoio con farina riservata. Cuoci subito o refrigera coperti per un massimo proposto di 2 ore prima della cottura.","image_url":"/recetas/receta-raviolis-caseros/paso-06.webp","image_alt":"Ravioli fatti in casa con ricotta e spinaci: Stendi, farcisci e sigilla"},{"title":"Cuoci i ravioli in due turni","content":"Fai bollire i 3 litri d’acqua con i 3 g di sale restanti. Intanto sciogli i 40 g di burro a fuoco medio-basso con la salvia finché profuma di nocciola e i solidi sono dorati, non neri; togli dal fuoco. Cuoci i ravioli in 2 turni per non farli attaccare: mescola piano e conta 3–5 minuti da quando riprende un bollore moderato. Apri un raviolo di prova del primo turno: pasta tenera, chiusura cotta e centro ad almeno 71 °C. Se manca, prolunga e controllane un altro.","image_url":"/recetas/receta-raviolis-caseros/paso-07.webp","image_alt":"Ravioli fatti in casa con ricotta e spinaci: Cuoci i ravioli in due turni"},{"title":"Finisci, servi e conserva","content":"Togli i ravioli con una schiumarola, scola pochi secondi e passa nella padella di burro e salvia. Muovi delicatamente 30–60 secondi senza romperli. Servi subito 6 ravioli a persona. Refrigera gli avanzi in contenitori bassi a 4 °C o meno entro 2 ore, o 1 ora se l’ambiente supera 32 °C; si propone consumo entro 2 giorni. Riscalda una sola volta fino a 74 °C al centro. Non conservare uovo crudo avanzato che abbia toccato farina o utensili non sanificati.","image_url":"/recetas/receta-raviolis-caseros/paso-08.webp","image_alt":"Ravioli fatti in casa con ricotta e spinaci: Finisci, servi e conserva"}],"notes":"Impasto e ripieno contengono grano, uovo e latte. La scheda non propone sostituzioni senza glutine, uovo o latte perché cambierebbero idratazione, struttura e nutrizione. Fai sgocciolare la ricotta al freddo e strizza bene gli spinaci. Risigilla ogni bordo aperto e non sovrapporre. Spessore di 1 mm, resa di 24 pezzi e tempi sono obiettivi editoriali da confermare in cucina. Per congelare, disponi i ravioli crudi separati su vassoio finché solidi, poi trasferisci; cuoci da congelati, prolunga quanto serve e verifica almeno 71 °C al centro. Non scongelare a temperatura ambiente.","nutrition":{"calories":598.4,"protein_g":26.5,"carbs_g":65.8,"fat_g":24.9,"saturated_fat_g":14.3,"fiber_g":3.3,"sugar_g":0.9,"sodium_mg":761,"estimated":true,"serving_size":"6 ravioli su 24 proposti, con un quarto della salsa","source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Otto schede SR Legacy verificate; pesi edibili proposti sommati e divisi per 4. Si contano tutti i 320 g di farina e i 40 g di burro, anche se può restare farina o salsa. Si contano prudentemente tutti i 5 g di sale benché parte dell’acqua salata venga scartata.","note":"Stima informativa, non analisi del piatto finito. Marca e umidità della ricotta, dimensione reale delle uova, farina non incorporata, acqua assorbita, formaggio e burro sugli utensili modificano il risultato. Quantità e resa attendono una prova in cucina.","inputs":[{"ingredient":"Farina di grano tenero per tutti gli usi","edible_grams":320,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"fiber_g":2.7,"fat_g":0.98,"carbs_g":76.31,"calories":364,"protein_g":10.33,"sodium_mg":2,"saturated_fat_g":0.155,"sugar_g":0.27},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"Uova grandi, senza guscio","edible_grams":150,"fdc_id":171287,"fdc_description":"Egg, whole, raw, fresh","per_100g":{"calories":143,"saturated_fat_g":3.126,"protein_g":12.56,"sodium_mg":142,"sugar_g":0.37,"fat_g":9.51,"carbs_g":0.72,"fiber_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171287/nutrients"},{"ingredient":"Ricotta di latte intero","edible_grams":300,"fdc_id":170851,"fdc_description":"Cheese, ricotta, whole milk","per_100g":{"calories":174,"protein_g":11.26,"carbs_g":3.04,"fat_g":12.98,"saturated_fat_g":8.295,"fiber_g":0,"sugar_g":0.27,"sodium_mg":84},"source_url":"https://fdc.nal.usda.gov/food-details/170851/nutrients"},{"ingredient":"Spinaci freschi","edible_grams":200,"fdc_id":168462,"fdc_description":"Spinach, raw","per_100g":{"calories":23,"protein_g":2.86,"carbs_g":3.63,"fat_g":0.39,"saturated_fat_g":0.063,"fiber_g":2.2,"sugar_g":0.42,"sodium_mg":79},"source_url":"https://fdc.nal.usda.gov/food-details/168462/nutrients"},{"ingredient":"Parmigiano grattugiato fine","edible_grams":40,"fdc_id":170848,"fdc_description":"Cheese, parmesan, hard","per_100g":{"calories":392,"protein_g":35.75,"carbs_g":3.22,"fat_g":25,"saturated_fat_g":16.41,"fiber_g":0,"sugar_g":0.8,"sodium_mg":1184},"source_url":"https://fdc.nal.usda.gov/food-details/170848/nutrients"},{"ingredient":"Burro non salato","edible_grams":40,"fdc_id":173430,"fdc_description":"Butter, without salt","per_100g":{"sugar_g":0.06,"calories":717,"saturated_fat_g":50.489,"fat_g":81.11,"carbs_g":0.06,"protein_g":0.85,"fiber_g":0,"sodium_mg":11},"source_url":"https://fdc.nal.usda.gov/food-details/173430/nutrients"},{"ingredient":"Noce moscata macinata","edible_grams":0.5,"fdc_id":171326,"fdc_description":"Spices, nutmeg, ground","per_100g":{"protein_g":5.84,"sodium_mg":16,"saturated_fat_g":25.94,"fat_g":36.31,"carbs_g":49.29,"calories":525,"sugar_g":2.99,"fiber_g":20.8},"source_url":"https://fdc.nal.usda.gov/food-details/171326/nutrients"},{"ingredient":"Sale fino","edible_grams":5,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0,"sodium_mg":38758,"saturated_fat_g":0,"protein_g":0,"fat_g":0,"carbs_g":0,"calories":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"}]},"keywords":["ravioli fatti in casa","ravioli ricotta e spinaci","pasta fresca per ravioli"],"image_url":"/recetas/receta-raviolis-caseros/portada.webp","gallery":[{"url":"/recetas/receta-raviolis-caseros/portada.webp","alt":"Ravioli fatti in casa con ricotta e spinaci, burro nocciola e foglie di salvia"}],"seo":{"title":"Ravioli fatti in casa con ricotta e spinaci","description":"Ravioli ricotta e spinaci per 4: pasta fresca all’uovo, chiusura passo passo e burro nocciola alla salvia.","image_alt":"Ravioli fatti in casa con ricotta e spinaci, burro nocciola e foglie di salvia","image_variants":["/recetas/receta-raviolis-caseros/portada-1x1.webp","/recetas/receta-raviolis-caseros/portada-4x3.webp","/recetas/receta-raviolis-caseros/portada-16x9.webp"],"faq":[{"q":"Perché i ravioli si aprono in cottura?","a":"Cause frequenti sono ripieno umido, aria intrappolata, farina sui bordi o sigillo debole. Sgocciola la ricotta, strizza gli spinaci, espelli l’aria e inumidisci appena il bordo prima di premere."},{"q":"Posso farli senza macchina per pasta?","a":"Sì, con mattarello e piccole porzioni. Cerca una sfoglia uniforme di circa 1 mm e tieni coperto l’impasto inutilizzato. Il lavoro può superare i 90 minuti proposti."},{"q":"Posso congelarli prima di cuocerli?","a":"Sì. Congelali crudi e separati su vassoio, poi trasferiscili. Cuoci da congelati, prolunga quanto serve e verifica almeno 71 °C al centro."}]},"published":false,"editorial_status":"draft","content_html":"<p>Questi ravioli fatti in casa uniscono pasta fresca all’uovo e un ripieno sodo di ricotta, spinaci e parmigiano. Si chiudono in 24 pezzi e si servono con burro nocciola e salvia, senza coprire la tecnica con una salsa pesante.</p><p>La proposta rende 4 porzioni da 6 ravioli. Calcola 70 minuti di preparazione e 20 di cottura, 90 in totale; sgocciolatura, riposo e parte del lavoro si sovrappongono. Quantità, spessore, tempi e resa attendono una prova in cucina.</p>"},{"id":"9eb92ac0-4c94-529c-ac97-3253fd394638","recipe_group_id":"e8238258-5fe1-4344-8851-917fa546f20b","slug":"homemade-ravioli","public_path":"/ja/homemade-ravioli","source_url":null,"language":"ja","title":"リコッタとほうれん草の手作りラビオリ","excerpt":"4人分の手作りラビオリ。卵入り生地、リコッタとほうれん草の詰め方、セージ入り焦がしバターまで説明します。","summary":"卵入りの生パスタに、リコッタ、ほうれん草、パルメザンの固めのフィリングを包む手作りラビオリです。24個に成形し、重いソースではなくセージ入り焦がしバターで仕上げます。\n\n6個ずつ4人分を想定します。準備70分、加熱20分、合計90分で、水切り、休ませる時間、ほかの準備は一部並行します。分量、生地の厚さ、時間、出来上がり数は調理試作による確認前です。","category":"パスタ","category_slug":"pastas","difficulty":"中級","course":"主菜","cuisine":"イタリア料理の家庭向け提案","prep_time_minutes":70,"cook_time_minutes":20,"total_time_minutes":90,"servings":4,"ingredients":[{"name":"中力粉または薄力粉と強力粉を合わせた小麦粉","amount":"320","unit":"g","group":"生地"},{"name":"殻を除いた大きめの卵","amount":"3","unit":"個（約150 g）","group":"生地"},{"name":"水","amount":"15","unit":"ml、必要な場合のみ","group":"生地"},{"name":"全乳リコッタ","amount":"300","unit":"g","group":"フィリング"},{"name":"生のほうれん草","amount":"200","unit":"g","group":"フィリング"},{"name":"細かくおろしたパルメザン","amount":"40","unit":"g","group":"フィリング"},{"name":"粉末ナツメグ","amount":"0.5","unit":"g","group":"フィリング"},{"name":"細粒塩","amount":"5","unit":"g、分けて使用"},{"name":"無塩バター","amount":"40","unit":"g","group":"仕上げ"},{"name":"生のセージの葉","amount":"6","unit":"g","group":"仕上げ"},{"name":"ゆで水","amount":"3000","unit":"ml","group":"加熱用"}],"steps":[{"title":"リコッタの水を切る","content":"リコッタ300 gをボウルに重ねた細かいこし器へ入れ、覆って冷蔵庫で30分水切りします。室温に放置しません。最後にやさしく押しますが、乾いたペーストにはしません。この待ち時間は準備70分に含み、生地やほうれん草の作業と並行できます。","image_url":"/recetas/receta-raviolis-caseros/paso-01.webp","image_alt":"リコッタとほうれん草の手作りラビオリ: リコッタの水を切る"},{"title":"ほうれん草を加熱して水気を取る","content":"ほうれん草200 gを洗い、ぬれたまま広いフライパンへ入れます。中火で混ぜながら2～3分、しんなりするまで加熱します。清潔な皿に広げ、触れられる温度になったら清潔な手または布でできるだけ水を絞り、細かく刻みます。水分が多いとラビオリが開くことがあります。","image_url":"/recetas/receta-raviolis-caseros/paso-02.webp","image_alt":"リコッタとほうれん草の手作りラビオリ: ほうれん草を加熱して水気を取る"},{"title":"生地を合わせる","content":"小麦粉300 gの中央にくぼみを作り、殻を除いて約150 gの卵3個を加えます。フォークで溶き、縁の粉を少しずつ取り込みます。固い生地にまとまるまでこね、数分後も乾いた部分が残る場合だけ水を5 mlずつ加えます。残り20 gの粉は台とトレー用に残します。吸水は変わるため、水を必ず全量加えません。","image_url":"/recetas/receta-raviolis-caseros/paso-03.webp","image_alt":"リコッタとほうれん草の手作りラビオリ: 生地を合わせる"},{"title":"こねて休ませる","content":"清潔な台で8～10分、生地が滑らかになり、押した跡がゆっくり戻るまでこねます。乾燥しないようしっかり包み、涼しい室温で30分休ませます。生卵に触れた台と器具は、フィリングや加熱済みラビオリを扱う前に洗浄します。","image_url":"/recetas/receta-raviolis-caseros/paso-04.webp","image_alt":"リコッタとほうれん草の手作りラビオリ: こねて休ませる"},{"title":"固めのフィリングを作る","content":"水切りしたリコッタ、刻んだほうれん草、パルメザン40 g、ナツメグ0.5 g、塩2 gを混ぜます。小さじ1杯の形を保つ固さが必要です。約20 gずつ24等分する目安をつけ、広がる、または水が出る場合は10分冷蔵して再確認します。この提案ではフィリングに卵を加えません。","image_url":"/recetas/receta-raviolis-caseros/paso-05.webp","image_alt":"リコッタとほうれん草の手作りラビオリ: 固めのフィリングを作る"},{"title":"伸ばして包み、閉じる","content":"生地を4分割し、3個は包んでおきます。1個を機械または麺棒で約1 mmに均一に伸ばし、穴を避けます。フィリング6個分を間隔を空けて置き、周囲を水でごく軽く湿らせ、シートの反対側をかぶせます。空気を外へ押し出して密着させ、6個に切って全周を確認します。24個まで繰り返し、残した粉を振ったトレーに重ねず並べます。すぐ加熱するか、覆って加熱前最長2時間という提案で冷蔵します。","image_url":"/recetas/receta-raviolis-caseros/paso-06.webp","image_alt":"リコッタとほうれん草の手作りラビオリ: 伸ばして包み、閉じる"},{"title":"2回に分けてゆでる","content":"水3リットルに残りの塩3 gを加えて沸かします。同時にバター40 gとセージを中弱火で溶かし、ナッツの香りがして乳固形分が金色、黒色ではない状態で火から外します。くっつかないようラビオリを2回に分け、やさしく混ぜ、穏やかな沸騰が戻ってから3～5分ゆでます。最初の1個を開き、生地と接着部が加熱され、中心が少なくとも71 °Cか確認します。足りなければ延長し、別の1個を確認します。","image_url":"/recetas/receta-raviolis-caseros/paso-07.webp","image_alt":"リコッタとほうれん草の手作りラビオリ: 2回に分けてゆでる"},{"title":"仕上げて盛り、保存する","content":"穴あきレードルですくい、数秒水を切ってセージバターへ移します。壊さないよう30～60秒やさしく動かします。1人6個をすぐ盛ります。残りは浅い容器に入れ、2時間以内、室温が32 °Cを超えるなら1時間以内に4 °C以下で冷蔵し、2日以内の使用を提案します。再加熱は1回だけ中心74 °Cまで。粉や未洗浄器具に触れた残りの生卵は保存しません。","image_url":"/recetas/receta-raviolis-caseros/paso-08.webp","image_alt":"リコッタとほうれん草の手作りラビオリ: 仕上げて盛り、保存する"}],"notes":"生地とフィリングは小麦、卵、乳を含みます。水分、構造、栄養が変わるため、このカードではグルテン、卵、乳を除く置換は提案しません。リコッタは冷蔵で水切りし、ほうれん草は十分絞ります。開いた縁はゆでる前に閉じ直し、重ねません。厚さ1 mm、24個、時間は調理確認前の編集上の目標です。冷凍する場合は生のラビオリを離してトレーで固め、容器へ移します。凍ったまま加熱し、必要に応じ時間を延ばし、中心71 °C以上を確認します。室温解凍はしません。","nutrition":{"calories":598.4,"protein_g":26.5,"carbs_g":65.8,"fat_g":24.9,"saturated_fat_g":14.3,"fiber_g":3.3,"sugar_g":0.9,"sodium_mg":761,"estimated":true,"serving_size":"提案する24個のうち6個とソース4分の1","source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"確認済みSR Legacy資料8件を使い、提案可食重量を合計して4で割っています。小麦粉320 gとバター40 gは、作業粉やソースが残る場合も全量計上。塩5 gは、塩を含むゆで水の一部を捨てる場合も保守的に全量計上しています。","note":"情報用の推定で完成品の分析値ではありません。リコッタの製品と水分、卵の実重量、取り込まれない粉、吸水、器具に残るチーズとバターで変わります。分量と出来上がり数は調理試作による確認前です。","inputs":[{"ingredient":"中力粉または薄力粉と強力粉を合わせた小麦粉","edible_grams":320,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"fiber_g":2.7,"fat_g":0.98,"carbs_g":76.31,"calories":364,"protein_g":10.33,"sodium_mg":2,"saturated_fat_g":0.155,"sugar_g":0.27},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"殻を除いた大きめの卵","edible_grams":150,"fdc_id":171287,"fdc_description":"Egg, whole, raw, fresh","per_100g":{"calories":143,"saturated_fat_g":3.126,"protein_g":12.56,"sodium_mg":142,"sugar_g":0.37,"fat_g":9.51,"carbs_g":0.72,"fiber_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171287/nutrients"},{"ingredient":"全乳リコッタ","edible_grams":300,"fdc_id":170851,"fdc_description":"Cheese, ricotta, whole milk","per_100g":{"calories":174,"protein_g":11.26,"carbs_g":3.04,"fat_g":12.98,"saturated_fat_g":8.295,"fiber_g":0,"sugar_g":0.27,"sodium_mg":84},"source_url":"https://fdc.nal.usda.gov/food-details/170851/nutrients"},{"ingredient":"生のほうれん草","edible_grams":200,"fdc_id":168462,"fdc_description":"Spinach, raw","per_100g":{"calories":23,"protein_g":2.86,"carbs_g":3.63,"fat_g":0.39,"saturated_fat_g":0.063,"fiber_g":2.2,"sugar_g":0.42,"sodium_mg":79},"source_url":"https://fdc.nal.usda.gov/food-details/168462/nutrients"},{"ingredient":"細かくおろしたパルメザン","edible_grams":40,"fdc_id":170848,"fdc_description":"Cheese, parmesan, hard","per_100g":{"calories":392,"protein_g":35.75,"carbs_g":3.22,"fat_g":25,"saturated_fat_g":16.41,"fiber_g":0,"sugar_g":0.8,"sodium_mg":1184},"source_url":"https://fdc.nal.usda.gov/food-details/170848/nutrients"},{"ingredient":"無塩バター","edible_grams":40,"fdc_id":173430,"fdc_description":"Butter, without salt","per_100g":{"sugar_g":0.06,"calories":717,"saturated_fat_g":50.489,"fat_g":81.11,"carbs_g":0.06,"protein_g":0.85,"fiber_g":0,"sodium_mg":11},"source_url":"https://fdc.nal.usda.gov/food-details/173430/nutrients"},{"ingredient":"粉末ナツメグ","edible_grams":0.5,"fdc_id":171326,"fdc_description":"Spices, nutmeg, ground","per_100g":{"protein_g":5.84,"sodium_mg":16,"saturated_fat_g":25.94,"fat_g":36.31,"carbs_g":49.29,"calories":525,"sugar_g":2.99,"fiber_g":20.8},"source_url":"https://fdc.nal.usda.gov/food-details/171326/nutrients"},{"ingredient":"細粒塩","edible_grams":5,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0,"sodium_mg":38758,"saturated_fat_g":0,"protein_g":0,"fat_g":0,"carbs_g":0,"calories":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"}]},"keywords":["手作りラビオリ","リコッタとほうれん草のラビオリ","ラビオリの生地"],"image_url":"/recetas/receta-raviolis-caseros/portada.webp","gallery":[{"url":"/recetas/receta-raviolis-caseros/portada.webp","alt":"リコッタとほうれん草の手作りラビオリ、焦がしバターとセージの葉"}],"seo":{"title":"リコッタとほうれん草の手作りラビオリ","description":"4人分の手作りラビオリ。卵入り生地、リコッタとほうれん草の詰め方、セージ入り焦がしバターまで説明します。","image_alt":"リコッタとほうれん草の手作りラビオリ、焦がしバターとセージの葉","image_variants":["/recetas/receta-raviolis-caseros/portada-1x1.webp","/recetas/receta-raviolis-caseros/portada-4x3.webp","/recetas/receta-raviolis-caseros/portada-16x9.webp"],"faq":[{"q":"ゆでるとラビオリが開くのはなぜですか？","a":"水分の多いフィリング、内部の空気、縁の粉、接着不足が主な原因です。リコッタを水切りし、ほうれん草を絞り、空気を抜き、押す前に周囲をわずかに湿らせます。"},{"q":"パスタマシンなしでも作れますか？","a":"はい。麺棒と小分けした生地を使い、約1 mmの均一なシートを目指します。使わない生地は覆います。作業は提案の90分を超える場合があります。"},{"q":"ゆでる前に冷凍できますか？","a":"はい。生のラビオリをトレーで離して冷凍し、容器へ移します。凍ったままゆで、必要な時間を追加し、中心が少なくとも71 °Cに達することを確認します。"}]},"published":false,"editorial_status":"draft","content_html":"<p>卵入りの生パスタに、リコッタ、ほうれん草、パルメザンの固めのフィリングを包む手作りラビオリです。24個に成形し、重いソースではなくセージ入り焦がしバターで仕上げます。</p><p>6個ずつ4人分を想定します。準備70分、加熱20分、合計90分で、水切り、休ませる時間、ほかの準備は一部並行します。分量、生地の厚さ、時間、出来上がり数は調理試作による確認前です。</p>"},{"id":"170a489c-2c0c-59c4-8b85-b1141e50ae74","recipe_group_id":"e8238258-5fe1-4344-8851-917fa546f20b","slug":"ravioli-caseiro","public_path":"/pt/ravioli-caseiro","source_url":null,"language":"pt","title":"Ravioli caseiro de ricota e espinafre","excerpt":"Ravioli caseiro de ricota e espinafre para 4: massa fresca com ovos, fechamento passo a passo e manteiga dourada com sálvia.","summary":"Este ravioli caseiro combina massa fresca de ovos com um recheio firme de ricota, espinafre e parmesão. São fechadas 24 unidades e servidas com manteiga dourada e sálvia, sem esconder a técnica sob um molho pesado.\n\nA proposta rende 4 porções de 6 raviolis. Calcule 70 minutos de preparo e 20 de cozimento, 90 no total; drenagem, descanso e parte do preparo se sobrepõem. Quantidades, espessura, tempos e rendimento aguardam teste de cozinha.","category":"Massas","category_slug":"pastas","difficulty":"Média","course":"Prato principal","cuisine":"Italiana, proposta caseira","prep_time_minutes":70,"cook_time_minutes":20,"total_time_minutes":90,"servings":4,"ingredients":[{"name":"Farinha de trigo de uso geral","amount":"320","unit":"g","group":"Massa"},{"name":"Ovos grandes, sem casca","amount":"3","unit":"ovos grandes (cerca de 150 g)","group":"Massa"},{"name":"Água","amount":"15","unit":"ml, somente se necessário","group":"Massa"},{"name":"Ricota de leite integral","amount":"300","unit":"g","group":"Recheio"},{"name":"Espinafre fresco","amount":"200","unit":"g","group":"Recheio"},{"name":"Queijo parmesão ralado fino","amount":"40","unit":"g","group":"Recheio"},{"name":"Noz-moscada moída","amount":"0.5","unit":"g","group":"Recheio"},{"name":"Sal fino","amount":"5","unit":"g, divididos"},{"name":"Manteiga sem sal","amount":"40","unit":"g","group":"Finalização"},{"name":"Folhas de sálvia fresca","amount":"6","unit":"g","group":"Finalização"},{"name":"Água para cozinhar","amount":"3000","unit":"ml","group":"Cozimento"}],"steps":[{"title":"Escorra a ricota","content":"Coloque os 300 g de ricota em uma peneira fina sobre uma tigela, cubra e deixe escorrer 30 minutos na geladeira. Não deixe em temperatura ambiente. Pressione de leve no final sem formar uma pasta seca. A espera entra nos 70 minutos de preparo e pode se sobrepor à massa e ao espinafre.","image_url":"/recetas/receta-raviolis-caseros/paso-01.webp","image_alt":"Ravioli caseiro de ricota e espinafre: Escorra a ricota"},{"title":"Cozinhe e seque o espinafre","content":"Lave os 200 g de espinafre e coloque ainda úmido em uma frigideira larga. Cozinhe 2–3 minutos em fogo médio, mexendo, até murchar. Espalhe em prato limpo para perder calor; quando puder tocar, esprema com mãos limpas ou pano limpo para tirar o máximo de água e pique fino. Espinafre úmido pode abrir os raviolis.","image_url":"/recetas/receta-raviolis-caseros/paso-02.webp","image_alt":"Ravioli caseiro de ricota e espinafre: Cozinhe e seque o espinafre"},{"title":"Misture a massa","content":"Faça um poço em 300 g de farinha e junte os 3 ovos, cerca de 150 g sem casca. Bata com garfo e incorpore farinha da borda aos poucos. Amasse até unir uma massa firme; acrescente água de 5 em 5 ml somente se restarem partes secas após vários minutos. Reserve os 20 g de farinha para bancada e assadeira. A absorção varia: não use toda a água por obrigação.","image_url":"/recetas/receta-raviolis-caseros/paso-03.webp","image_alt":"Ravioli caseiro de ricota e espinafre: Misture a massa"},{"title":"Sove e deixe descansar","content":"Sove 8–10 minutos em superfície limpa até a massa ficar lisa e voltar devagar ao ser pressionada. Embrulhe bem para não ressecar e descanse 30 minutos em temperatura ambiente fresca. Higienize bancada e utensílios que tocaram ovo cru antes do recheio ou de raviolis cozidos.","image_url":"/recetas/receta-raviolis-caseros/paso-04.webp","image_alt":"Ravioli caseiro de ricota e espinafre: Sove e deixe descansar"},{"title":"Faça um recheio seco","content":"Misture ricota escorrida, espinafre picado, 40 g de parmesão, 0,5 g de noz-moscada e 2 g de sal. Deve ficar espesso e manter o formato de uma colher de chá. Divida visualmente em 24 porções de cerca de 20 g; se espalhar ou soltar líquido, refrigere 10 minutos e confira de novo. Não acrescente ovo a este recheio proposto.","image_url":"/recetas/receta-raviolis-caseros/paso-05.webp","image_alt":"Ravioli caseiro de ricota e espinafre: Faça um recheio seco"},{"title":"Abra, recheie e feche","content":"Divida a massa em 4 partes e mantenha 3 embrulhadas. Abra uma parte na máquina ou rolo até cerca de 1 mm, sem furos. Coloque 6 porções espaçadas, umedeça quase nada o contorno e cubra com a outra metade. Expulse o ar e pressione para fechar. Corte 6 raviolis e confira cada borda. Repita até 24; ponha sem empilhar em assadeira com farinha reservada. Cozinhe na hora ou refrigere cobertos por no máximo 2 horas propostas antes do cozimento.","image_url":"/recetas/receta-raviolis-caseros/paso-06.webp","image_alt":"Ravioli caseiro de ricota e espinafre: Abra, recheie e feche"},{"title":"Cozinhe em duas levas","content":"Ferva os 3 litros de água com os 3 g de sal restantes. Enquanto isso, derreta os 40 g de manteiga em fogo médio-baixo com a sálvia até cheirar a avelã e os sólidos ficarem dourados, não pretos; tire do fogo. Cozinhe em 2 levas para não grudar: mexa com cuidado e conte 3–5 minutos após voltar a fervura moderada. Abra um ravioli de teste da primeira leva: massa macia, selo cozido e centro a pelo menos 71 °C. Se não, prolongue e teste outro.","image_url":"/recetas/receta-raviolis-caseros/paso-07.webp","image_alt":"Ravioli caseiro de ricota e espinafre: Cozinhe em duas levas"},{"title":"Finalize, sirva e guarde","content":"Retire com escumadeira, escorra por segundos e passe para a frigideira de manteiga e sálvia. Mexa com cuidado 30–60 segundos sem romper. Sirva na hora 6 raviolis por pessoa. Refrigere sobras em recipientes baixos a 4 °C ou menos em até 2 horas, ou 1 hora se o ambiente passar de 32 °C; propõe-se consumo em 2 dias. Reaqueça uma vez até 74 °C no centro. Não guarde ovo cru restante que tocou farinha ou utensílios não higienizados.","image_url":"/recetas/receta-raviolis-caseros/paso-08.webp","image_alt":"Ravioli caseiro de ricota e espinafre: Finalize, sirva e guarde"}],"notes":"Massa e recheio contêm trigo, ovo e leite. A ficha não propõe substituições sem glúten, ovo ou leite porque mudariam hidratação, estrutura e nutrição. Escorra a ricota no frio e esprema bem o espinafre. Sele qualquer borda aberta antes de cozinhar e não empilhe. Espessura de 1 mm, rendimento de 24 unidades e tempos são objetivos editoriais aguardando confirmação em cozinha. Para congelar, separe os raviolis crus em assadeira até firmarem e transfira; cozinhe congelados, aumente o tempo conforme necessário e confira ao menos 71 °C no centro. Não descongele em temperatura ambiente.","nutrition":{"calories":598.4,"protein_g":26.5,"carbs_g":65.8,"fat_g":24.9,"saturated_fat_g":14.3,"fiber_g":3.3,"sugar_g":0.9,"sodium_mg":761,"estimated":true,"serving_size":"6 raviolis de um total proposto de 24, com um quarto do molho","source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Oito fichas SR Legacy verificadas; pesos comestíveis propostos somados e divididos por 4. Contam-se todos os 320 g de farinha e os 40 g de manteiga, embora possa sobrar farinha de trabalho ou molho. Contam-se de forma conservadora todos os 5 g de sal, ainda que parte da água salgada seja descartada.","note":"Estimativa informativa, não análise do prato pronto. Marca e umidade da ricota, tamanho real dos ovos, farinha não incorporada, água absorvida, queijo e manteiga nos utensílios alteram o resultado. Quantidades e rendimento aguardam teste de cozinha.","inputs":[{"ingredient":"Farinha de trigo de uso geral","edible_grams":320,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"fiber_g":2.7,"fat_g":0.98,"carbs_g":76.31,"calories":364,"protein_g":10.33,"sodium_mg":2,"saturated_fat_g":0.155,"sugar_g":0.27},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"Ovos grandes, sem casca","edible_grams":150,"fdc_id":171287,"fdc_description":"Egg, whole, raw, fresh","per_100g":{"calories":143,"saturated_fat_g":3.126,"protein_g":12.56,"sodium_mg":142,"sugar_g":0.37,"fat_g":9.51,"carbs_g":0.72,"fiber_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171287/nutrients"},{"ingredient":"Ricota de leite integral","edible_grams":300,"fdc_id":170851,"fdc_description":"Cheese, ricotta, whole milk","per_100g":{"calories":174,"protein_g":11.26,"carbs_g":3.04,"fat_g":12.98,"saturated_fat_g":8.295,"fiber_g":0,"sugar_g":0.27,"sodium_mg":84},"source_url":"https://fdc.nal.usda.gov/food-details/170851/nutrients"},{"ingredient":"Espinafre fresco","edible_grams":200,"fdc_id":168462,"fdc_description":"Spinach, raw","per_100g":{"calories":23,"protein_g":2.86,"carbs_g":3.63,"fat_g":0.39,"saturated_fat_g":0.063,"fiber_g":2.2,"sugar_g":0.42,"sodium_mg":79},"source_url":"https://fdc.nal.usda.gov/food-details/168462/nutrients"},{"ingredient":"Queijo parmesão ralado fino","edible_grams":40,"fdc_id":170848,"fdc_description":"Cheese, parmesan, hard","per_100g":{"calories":392,"protein_g":35.75,"carbs_g":3.22,"fat_g":25,"saturated_fat_g":16.41,"fiber_g":0,"sugar_g":0.8,"sodium_mg":1184},"source_url":"https://fdc.nal.usda.gov/food-details/170848/nutrients"},{"ingredient":"Manteiga sem sal","edible_grams":40,"fdc_id":173430,"fdc_description":"Butter, without salt","per_100g":{"sugar_g":0.06,"calories":717,"saturated_fat_g":50.489,"fat_g":81.11,"carbs_g":0.06,"protein_g":0.85,"fiber_g":0,"sodium_mg":11},"source_url":"https://fdc.nal.usda.gov/food-details/173430/nutrients"},{"ingredient":"Noz-moscada moída","edible_grams":0.5,"fdc_id":171326,"fdc_description":"Spices, nutmeg, ground","per_100g":{"protein_g":5.84,"sodium_mg":16,"saturated_fat_g":25.94,"fat_g":36.31,"carbs_g":49.29,"calories":525,"sugar_g":2.99,"fiber_g":20.8},"source_url":"https://fdc.nal.usda.gov/food-details/171326/nutrients"},{"ingredient":"Sal fino","edible_grams":5,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0,"sodium_mg":38758,"saturated_fat_g":0,"protein_g":0,"fat_g":0,"carbs_g":0,"calories":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"}]},"keywords":["ravioli caseiro","ravioli de ricota e espinafre","massa fresca para ravioli"],"image_url":"/recetas/receta-raviolis-caseros/portada.webp","gallery":[{"url":"/recetas/receta-raviolis-caseros/portada.webp","alt":"Ravioli caseiro de ricota e espinafre com manteiga dourada e folhas de sálvia"}],"seo":{"title":"Ravioli caseiro de ricota e espinafre","description":"Ravioli caseiro de ricota e espinafre para 4: massa fresca com ovos, fechamento passo a passo e manteiga dourada com sálvia.","image_alt":"Ravioli caseiro de ricota e espinafre com manteiga dourada e folhas de sálvia","image_variants":["/recetas/receta-raviolis-caseros/portada-1x1.webp","/recetas/receta-raviolis-caseros/portada-4x3.webp","/recetas/receta-raviolis-caseros/portada-16x9.webp"],"faq":[{"q":"Por que os raviolis abrem no cozimento?","a":"As causas comuns são recheio úmido, ar preso, farinha nas bordas ou fechamento fraco. Escorra a ricota, esprema o espinafre, expulse o ar e umedeça quase nada o contorno antes de pressionar."},{"q":"Posso fazer sem máquina de massa?","a":"Sim, com rolo e pequenas porções. Busque uma folha uniforme de cerca de 1 mm e mantenha coberta a massa que não usar. O trabalho pode passar dos 90 minutos propostos."},{"q":"Posso congelar antes de cozinhar?","a":"Sim. Congele os raviolis crus separados em assadeira e depois transfira. Cozinhe congelados, aumente o tempo conforme necessário e confira pelo menos 71 °C no centro."}]},"published":false,"editorial_status":"draft","content_html":"<p>Este ravioli caseiro combina massa fresca de ovos com um recheio firme de ricota, espinafre e parmesão. São fechadas 24 unidades e servidas com manteiga dourada e sálvia, sem esconder a técnica sob um molho pesado.</p><p>A proposta rende 4 porções de 6 raviolis. Calcule 70 minutos de preparo e 20 de cozimento, 90 no total; drenagem, descanso e parte do preparo se sobrepõem. Quantidades, espessura, tempos e rendimento aguardam teste de cozinha.</p>"}]$ravioli$::jsonb;
