begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and recipe_group_id = g and language = 'es' and published = false and slug = 'receta-raviolis-caseros' and public_path = '/receta-raviolis-caseros') then
    raise exception 'Estado previo inesperado del grupo receta-raviolis-caseros';
