    content_html=coalesce(x.content_html,''), notes=x.notes, difficulty=x.difficulty, course=x.course,
    cuisine=x.cuisine, keywords=x.keywords, nutrition=x.nutrition, gallery=x.gallery, seo=x.seo,
    editorial_status='published', ready_at=ts, published=true
  from jsonb_populate_recordset(null::public.recipes,j) x where r.id=es_id and x.language='es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES de receta-raviolis-caseros afectó % filas', n; end if;
  insert into public.recipes (id,recipe_group_id,language,slug,public_path,source_url,title,excerpt,summary,ingredients,steps,category,prep_time_minutes,cook_time_minutes,total_time_minutes,servings,image_url,content_html,notes,difficulty,course,cuisine,keywords,nutrition,gallery,seo,editorial_status,ready_at,published)
  select x.id,g,x.language,x.slug,x.public_path,null,x.title,x.excerpt,x.summary,x.ingredients,x.steps,x.category,x.prep_time_minutes,x.cook_time_minutes,x.total_time_minutes,x.servings,x.image_url,coalesce(x.content_html,''),x.notes,x.difficulty,x.course,x.cuisine,x.keywords,x.nutrition,x.gallery,x.seo,'published',ts,true
  from jsonb_populate_recordset(null::public.recipes,j) x where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT de traducciones de receta-raviolis-caseros afectó % filas', n; end if;
  if (select count(*) from public.recipes where recipe_group_id=g and published and editorial_status='published' and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo receta-raviolis-caseros no quedó con 7 filas publicadas';
  end if;
  if (select count(distinct language) from public.recipes where recipe_group_id=g) <> 7 then
    raise exception 'El grupo receta-raviolis-caseros no quedó con 7 idiomas únicos';
  end if;
end
$pub$;
